// Pseudo-code sketch: redaction path
function redactPromptsAndOutputs(prompt, policy) {
  const redactedIn = applyRedaction(prompt, policy.inputRules);
  const redactedOut = applyRedaction(await llm(redactedIn), policy.outputRules);
  return { redactedIn, redactedOut };
}
```

